};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_goWriteReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30601.tx_fn_goWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_searchReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30601.tx_fn_search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_92").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name scwin.tx_fn_viewLecrDipt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_viewLecrDipt = async function () {
    const sbmOptions = {
        id: "tx_fn_viewLecrDipt",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_viewLecrDiptReq",
        target: "dlt_lecrDiptList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30601.tx_fn_viewLecrDipt" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_lecrDiptList_fmt_lecrDiptProcsStatNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_lecrDiptList_fmt_lecrDiptProcsStatNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_lecrDiptList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "lecrDiptProcsStatNm") ?? '') : '');
        if (v === '') { return "임시저장"; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "lecrDiptProcsStatNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_lecrDiptList.lecrDiptProcsStatNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('method', 'writeLecrDipt');
    { const nr = await scwin.tx_fn_goWrite(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30602/jldfil30602.xml", { "method": 'writeLecrDipt' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('method', 'searchLecrDipt');
    await scwin.tx_fn_search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewLecrDipt
 * @author Inswave
 * @date 2026. 09. 29
 * @param eduApplSeq lecrDiptProcsStatNm
 * @returns
 * @hidden N
*/
scwin.viewLecrDipt = async function (eduApplSeq, lecrDiptProcsStatNm) {
    /* sdd-asis-lifecycle:begin fn_viewLecrDipt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.LecrDiptForm || { elements: [] });
    if (lecrDiptProcsStatNm === '') {
        $c.util.getComponent('dma_goWriteReq').set('method', 'modifyLecrDipt');
        $c.util.getComponent('dma_goWriteReq').set('modifyYn', 'Y');
    } else {
        $c.util.getComponent('dma_goWriteReq').set('method', 'viewLecrDipt');
    }
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goWriteReq').set('eduApplSeq', eduApplSeq);
    { const nr = await scwin.tx_fn_viewLecrDipt(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30604/jldfil30604.xml", { "method": 'modifyLecrDipt', "modifyYn": 'Y', "eduApplSeq": eduApplSeq }); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_92_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_92_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_92.page' }); } scwin.tx_fn_search(); };
